(function() {
    'use strict';

    class BridgeCommAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'BridgeComm: Cross-Cultural Communication';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    nameEn: 'Initial Outreach & Meeting Design',
                    nameEs: 'Primer Contacto y Agenda',
                    briefingEn: '<strong>Round 1: Initial Outreach</strong><br><br>You are Dr. Klaus Maurer, VP of International Business Development at VantageAxis GmbH. Following a brief encounter with Nakamura Hiroshi, General Manager at Yokogawa Precision Systems, at Hannover Messe last April, you are preparing your first formal outreach.<br><br>Your task: Draft the initial contact email and propose a meeting format. Every word, every tone choice, and every structural decision in your communication will shape how Yokogawa perceives VantageAxis as a potential long-term partner.<br><br>Remember: Yokogawa operates within a high-context communication culture. Relationship precedes business. Hierarchy commands respect. Directness can signal aggression rather than efficiency.',
                    briefingEs: '<strong>Ronda 1: Primer Contacto</strong><br><br>Usted es el Dr. Klaus Maurer, VP de Desarrollo de Negocios Internacionales en VantageAxis GmbH. Tras un breve encuentro con Nakamura Hiroshi, Gerente General de Yokogawa Precision Systems, en Hannover Messe en abril pasado, prepara su primer contacto formal.<br><br>Su tarea: Redactar el correo inicial y proponer un formato de encuentro. Cada palabra y cada tono influyen en la manera en que Yokogawa le percibe como socio potencial a largo plazo.',
                    decisions: [
                        {
                            id: 'emailFormality',
                            labelEn: 'Email Opening Formality',
                            labelEs: 'Formalidad de Apertura del Correo',
                            options: [
                                { value: 'A', textEn: 'Dear Mr. Nakamura, I am writing to propose a partnership discussion...', textEs: 'Estimado Sr. Nakamura, le escribo para proponer...', trust: 0, dims: { cultural: 1, comm: 1 } },
                                { value: 'B', textEn: 'Dear Nakamura-san, Following our conversation at Hannover Messe last April, I wanted to continue our dialogue...', textEs: 'Estimado Nakamura-san, siguiendo nuestra charla en Hannover Messe...', trust: 6, dims: { cultural: 3, comm: 3 } },
                                { value: 'C', textEn: 'Dear Hiroshi, I wanted to reach out about a potential deal...', textEs: 'Estimado Hiroshi, quiero contactarte sobre un posible acuerdo...', trust: -8, dims: { cultural: -2, face: -2 } },
                                { value: 'D', textEn: 'To Whom It May Concern at Yokogawa Precision Systems...', textEs: 'A quien corresponda en Yokogawa Precision Systems...', trust: -12, dims: { cultural: -4, face: -3 } }
                            ]
                        },
                        {
                            id: 'commercialPosition',
                            labelEn: 'Commercial Objective Positioning',
                            labelEs: 'Posicionamiento del Objetivo Comercial',
                            options: [
                                { value: 'A', textEn: 'State full JV commercial objectives, revenue targets, and term-sheet expectations in opening email', textEs: 'Declarar todos los objetivos comerciales y expectativas en el correo inicial', trust: -10, dims: { cultural: -3, comm: -3 } },
                                { value: 'B', textEn: 'Reference shared strategic interest in ASEAN markets; propose meeting to explore collaboration possibilities', textEs: 'Referir al interes estrategico compartido; proponer encuentro exploratorio', trust: 5, dims: { cultural: 2, comm: 2 } },
                                { value: 'C', textEn: 'Attach detailed AxisSense technical specifications and integration requirements', textEs: 'Adjuntar especificaciones tecnicas detalladas de AxisSense', trust: -7, dims: { cultural: -2, process: -1 } },
                                { value: 'D', textEn: 'Mention only the Hannover Messe discussion warmly; propose dinner rather than formal meeting as first step', textEs: 'Mencionar solo Hannover Messe; proponer cena en lugar de reunion formal', trust: 9, dims: { cultural: 4, comm: 3 } }
                            ]
                        },
                        {
                            id: 'meetingDate',
                            labelEn: 'Meeting Date Proposal Approach',
                            labelEs: 'Enfoque para Proponer Fecha',
                            options: [
                                { value: 'A', textEn: 'I am available March 14-16 and would welcome your guidance on the most convenient date.', textEs: 'Estoy disponible del 14 al 16 de marzo y agradeceria su orientacion sobre la fecha mas conveniente.', trust: 6, dims: { face: 2, comm: 2 } },
                                { value: 'B', textEn: 'Please confirm March 15 for our meeting at your Osaka headquarters.', textEs: 'Por favor confirme el 15 de marzo para nuestra reunion.', trust: -8, dims: { face: -3, comm: -2 } },
                                { value: 'C', textEn: 'At your convenience, I would be honored to visit Osaka whenever your schedule permits.', textEs: 'Cuando le sea conveniente, seria un honor visitar Osaka.', trust: 4, dims: { face: 2, comm: 1 } },
                                { value: 'D', textEn: 'Propose a video call as the first meeting to save travel time and costs.', textEs: 'Proponer videollamada como primera reunion para ahorrar tiempo y costos.', trust: -11, dims: { cultural: -4, comm: -3 } }
                            ]
                        }
                    ]
                },
                {
                    nameEn: 'First Meeting Protocol',
                    nameEs: 'Protocolo del Primer Encuentro',
                    briefingEn: '<strong>Round 2: First Meeting in Osaka</strong><br><br>You have arrived at Yokogawa Precision Systems headquarters in Osaka. The Yokogawa team — led by Nakamura-san with Tanaka-san (Senior Engineer) and Matsumoto Keiko (Legal Affairs) — has arranged a formal welcome.<br><br>How you structure this first face-to-face encounter will determine whether Yokogawa sees you as a partner who understands the rhythm of Japanese business relationships, or as another impatient Western company rushing toward a contract.<br><br>The decisions you make about time allocation, language choices, and social protocol will either build the trust foundation for a successful JV — or erode it before the business discussion begins.',
                    briefingEs: '<strong>Ronda 2: Primer Encuentro en Osaka</strong><br><br>Ha llegado a la sede de Yokogawa en Osaka. El equipo de Yokogawa le ha preparado una bienvenida formal. La manera en que estructura este encuentro determinara si Yokogawa le ve como un socio que comprende el ritmo de las relaciones comerciales japonesas.',
                    decisions: [
                        {
                            id: 'relationshipTime',
                            labelEn: 'Relationship-Investment Time Before Business',
                            labelEs: 'Tiempo de Relacion Antes de Negocios',
                            options: [
                                { value: 'A', textEn: '5 minutes — brief introductions, then straight to business agenda', textEs: '5 minutos — presentaciones breves, luego a la agenda', trust: -9, dims: { cultural: -3, comm: -2 } },
                                { value: 'B', textEn: '15 minutes — standard introductions and general discussion', textEs: '15 minutos — presentaciones estandar y charla general', trust: -3, dims: { cultural: 0, comm: 0 } },
                                { value: 'C', textEn: '30 minutes — extended personal conversation and facility tour', textEs: '30 minutos — conversacion extendida y recorrido por las instalaciones', trust: 8, dims: { cultural: 3, comm: 2 } },
                                { value: 'D', textEn: '45 minutes — full relationship session including Yokogawa company history presentation and team introductions', textEs: '45 minutos — sesion completa de relacion incluyendo historia de Yokogawa', trust: 12, dims: { cultural: 4, comm: 3, face: 2 } }
                            ]
                        },
                        {
                            id: 'agreementChecking',
                            labelEn: 'Agreement-Checking Language',
                            labelEs: 'Lenguaje de Verificacion de Acuerdo',
                            options: [
                                { value: 'A', textEn: '"Do you agree with this approach? Yes or no?"', textEs: '"Esta de acuerdo con este enfoque? Si o no?"', trust: -10, dims: { face: -4, comm: -3 } },
                                { value: 'B', textEn: '"We wonder if this direction might offer some value from your perspective as well."', textEs: '"Nos preguntamos si esta direccion podria ofrecer valor desde su perspectiva."', trust: 6, dims: { face: 2, comm: 3 } },
                                { value: 'C', textEn: '"What aspects of this approach seem most promising from the Yokogawa perspective?"', textEs: '"Que aspectos de este enfoque parecen mas prometedores desde la perspectiva de Yokogawa?"', trust: 8, dims: { face: 3, comm: 3 } },
                                { value: 'D', textEn: 'No explicit agreement-checking; proceed assuming alignment', textEs: 'Sin verificacion explicita; proceder asumiendo alineacion', trust: -5, dims: { cultural: -1, comm: -2 } }
                            ]
                        },
                        {
                            id: 'hospitalityResponse',
                            labelEn: 'Response to Dinner Invitation',
                            labelEs: 'Respuesta a Invitacion a Cena',
                            options: [
                                { value: 'A', textEn: 'Accept enthusiastically but make no reciprocal offer', textEs: 'Aceptar con entusiasmo sin ofrecer reciprocidad', trust: 3, dims: { cultural: 1, face: 0 } },
                                { value: 'B', textEn: 'Decline due to jet lag; propose a quick breakfast meeting instead', textEs: 'Declinar por jet lag; proponer desayuno rapido', trust: -8, dims: { cultural: -3, face: -2 } },
                                { value: 'C', textEn: 'Accept warmly and offer to host a reciprocal dinner in Stuttgart at the next meeting', textEs: 'Aceptar con calidez y ofrecer cena reciproca en Stuttgart', trust: 10, dims: { cultural: 3, face: 2, comm: 2 } },
                                { value: 'D', textEn: 'Accept and ask if spouses are invited to the dinner', textEs: 'Aceptar y preguntar si las parejas estan invitadas', trust: -4, dims: { cultural: -2, face: -1 } }
                            ]
                        }
                    ]
                },
                {
                    nameEn: 'Technical Negotiation & Interpreter Management',
                    nameEs: 'Negociacion Tecnica y Gestion del Interprete',
                    briefingEn: '<strong>Round 3: Technical Negotiation Intensifies</strong><br><br>The AxisSense integration specifications are now on the table. Tanaka-san has proposed component tolerance specifications that differ from VantageAxis standards. The afternoon session will be conducted through a Japanese-English interpreter.<br><br>Three critical moments will test your cultural competence: a technical disagreement with face-saving implications, an interpreter management decision that will determine specification accuracy, and a pivotal silence from Nakamura-san after your legal team presents the IP-sharing clause.<br><br>How you navigate these moments will either cement trust or fracture it irreparably.',
                    briefingEs: '<strong>Ronda 3: La Negociacion Tecnica se Intensifica</strong><br><br>Las especificaciones de integracion de AxisSense estan sobre la mesa. Tanaka-san ha propuesto tolerancias que difieren de los estandares de VantageAxis. La sesion de la tarde sera con interprete. Tres momentos criticos pondran a prueba su competencia cultural.',
                    decisions: [
                        {
                            id: 'specDisagreement',
                            labelEn: 'Response to Specification Disagreement with Tanaka-san',
                            labelEs: 'Respuesta al Desacuerdo de Especificaciones con Tanaka-san',
                            options: [
                                { value: 'A', textEn: 'Thomas Becker directly states in front of both teams: "This specification will not work for our manufacturing process."', textEs: 'Thomas Becker declara directamente frente a ambos equipos: "Esta especificacion no funcionara."', trust: -15, dims: { face: -5, comm: -3, cultural: -3 } },
                                { value: 'B', textEn: 'Klaus Maurer suggests: "Perhaps we might explore this further in a smaller working group to ensure we fully understand the requirements."', textEs: 'Klaus Maurer sugiere explorar esto en un grupo de trabajo mas pequeno.', trust: 8, dims: { face: 3, comm: 2, cultural: 2 } },
                                { value: 'C', textEn: 'Klaus Maurer thanks Tanaka-san for the detailed proposal and suggests sending written comments for review before the next session.', textEs: 'Klaus Maurer agradece a Tanaka-san y propone enviar comentarios escritos.', trust: 10, dims: { face: 4, comm: 3, cultural: 2 } },
                                { value: 'D', textEn: 'Sandra Hoffmann states: "This needs resolution today. We have a board presentation next week."', textEs: 'Sandra Hoffmann declara que esto debe resolverse hoy por la presentacion al directorio.', trust: -14, dims: { face: -4, comm: -3, cultural: -3 } },
                                { value: 'E', textEn: 'The team goes silent and hopes the issue resolves itself in subsequent discussions.', textEs: 'El equipo guarda silencio y espera que se resuelva solo.', trust: -6, dims: { cultural: -1, process: -2 } }
                            ]
                        },
                        {
                            id: 'interpreterBriefing',
                            labelEn: 'Interpreter Briefing Before Afternoon Technical Session',
                            labelEs: 'Preparacion del Interprete Antes de la Sesion Tecnica',
                            options: [
                                { value: 'A', textEn: 'No interpreter briefing — proceed directly to the session', textEs: 'Sin preparacion del interprete — proceder directamente', trust: -6, dims: { process: -3, cultural: -1 } },
                                { value: 'B', textEn: 'Provide a technical vocabulary list only', textEs: 'Proporcionar solo lista de vocabulario tecnico', trust: 0, dims: { process: 1 } },
                                { value: 'C', textEn: 'Technical vocabulary list plus pace management protocol for complex passages', textEs: 'Lista de vocabulario mas protocolo de ritmo para pasajes complejos', trust: 5, dims: { process: 3, cultural: 1 } },
                                { value: 'D', textEn: 'Full briefing: vocabulary, cultural sensitivity notes, back-translation request for the summary document, and pace protocol', textEs: 'Preparacion completa: vocabulario, sensibilidad cultural, retrotraduccion y protocolo de ritmo', trust: 9, dims: { process: 4, cultural: 2, comm: 1 } }
                            ]
                        },
                        {
                            id: 'silenceResponse',
                            labelEn: 'Response to Nakamura-san Going Silent for 3 Minutes After IP Clause Presentation',
                            labelEs: 'Respuesta al Silencio de 3 Minutos de Nakamura-san Tras la Clausula de PI',
                            options: [
                                { value: 'A', textEn: 'Fill the silence with additional arguments supporting the IP-sharing clause', textEs: 'Llenar el silencio con argumentos adicionales sobre la clausula de PI', trust: -12, dims: { face: -4, cultural: -3, comm: -2 } },
                                { value: 'B', textEn: 'Wait in respectful silence, maintaining composed and patient body language', textEs: 'Esperar en silencio respetuoso con lenguaje corporal paciente', trust: 10, dims: { face: 3, cultural: 4, comm: 2 } },
                                { value: 'C', textEn: 'Gently redirect the conversation to a different contract clause', textEs: 'Redirigir suavemente la conversacion a otra clausula', trust: 3, dims: { face: 1, comm: 1 } },
                                { value: 'D', textEn: '"Is there a concern with this clause we could address together?"', textEs: '"Hay alguna preocupacion sobre esta clausula que podamos abordar juntos?"', trust: 6, dims: { face: 2, comm: 2, cultural: 1 } },
                                { value: 'E', textEn: 'Sandra Hoffmann says: "We need an answer on this clause today."', textEs: 'Sandra Hoffmann dice: "Necesitamos respuesta hoy."', trust: -20, dims: { face: -6, cultural: -5, comm: -4 } }
                            ]
                        }
                    ]
                },
                {
                    nameEn: 'Final Deal Structuring',
                    nameEs: 'Estructuracion Final del Acuerdo',
                    briefingEn: '<strong>Round 4: The Final Session</strong><br><br>This is the decisive meeting. Your accumulated Partnership Readiness Index determines what deal terms Yokogawa is willing to offer.<br><br>A surprise complication: Nakamura-san casually mentions through a fishing metaphor that "sometimes the best fish are the ones that swim to you, rather than the ones you chase across the ocean." This is an indirect reference to a Korean competitor that has approached Yokogawa informally.<br><br>How you respond to this signal — and how you approach the final deal — will determine whether AxisYoko Manufacturing Solutions becomes a reality, and on what terms.',
                    briefingEs: '<strong>Ronda 4: La Sesion Decisiva</strong><br><br>Esta es la reunion decisiva. Su indice de preparacion acumulado determina que terminos ofrece Yokogawa.<br><br>Complicacion: Nakamura-san menciona mediante una metafora de pesca que "a veces los mejores peces son los que nadan hacia ti." Es una referencia indirecta a un competidor coreano.',
                    decisions: [
                        {
                            id: 'competitiveResponse',
                            labelEn: 'Response to Competitive Approach Signal (Fishing Metaphor)',
                            labelEs: 'Respuesta a la Senal del Competidor (Metafora de Pesca)',
                            options: [
                                { value: 'A', textEn: 'Acknowledge the metaphor indirectly; express quiet confidence in the unique value VantageAxis brings to the partnership', textEs: 'Reconocer la metafora indirectamente; expresar confianza tranquila en el valor unico de VantageAxis', trust: 10, dims: { cultural: 4, comm: 3, face: 2 } },
                                { value: 'B', textEn: 'Ask directly: "Which Korean company has approached you? We need to know our competition."', textEs: 'Preguntar directamente que empresa coreana se ha acercado', trust: -8, dims: { cultural: -3, face: -2, comm: -2 } },
                                { value: 'C', textEn: 'Dismiss the competitor and emphasize urgency: "We should finalize this deal before other parties complicate matters."', textEs: 'Desestimar al competidor y enfatizar urgencia para cerrar', trust: -11, dims: { cultural: -4, comm: -3, face: -2 } },
                                { value: 'D', textEn: 'Thank Nakamura-san for his openness and reaffirm the long-term commitment VantageAxis has to this partnership beyond any single transaction', textEs: 'Agradecer la apertura y reafirmar el compromiso a largo plazo de VantageAxis', trust: 7, dims: { cultural: 3, comm: 2, face: 1 } }
                            ]
                        },
                        {
                            id: 'dealStance',
                            labelEn: 'Deal Negotiation Approach',
                            labelEs: 'Enfoque de Negociacion del Acuerdo',
                            options: [
                                { value: 'A', textEn: 'Push for maximum VantageAxis terms: highest revenue share, broadest exclusivity, full IP control', textEs: 'Presionar por terminos maximos: mayor participacion, exclusividad total', trust: -10, dims: { face: -3, comm: -3, cultural: -2 } },
                                { value: 'B', textEn: 'Express appreciation for the journey together and propose balanced terms reflecting mutual benefit and shared risk', textEs: 'Expresar aprecio por el camino recorrido y proponer terminos equilibrados', trust: 8, dims: { cultural: 3, comm: 3, face: 2 } },
                                { value: 'C', textEn: 'Accept whatever terms Yokogawa proposes without negotiation to demonstrate trust', textEs: 'Aceptar lo que Yokogawa proponga sin negociar para demostrar confianza', trust: 2, dims: { cultural: 1, comm: 0 } },
                                { value: 'D', textEn: 'Propose a phased agreement: start with limited scope, expand based on demonstrated results and deepening relationship', textEs: 'Proponer acuerdo por fases: comenzar limitado, expandir segun resultados', trust: 6, dims: { cultural: 2, comm: 2, process: 2 } }
                            ]
                        }
                    ]
                }
            ];

            this.RANDOM_EVENTS = [
                {
                    id: 'late_arrival',
                    textEn: '<strong>Complication:</strong> Nakamura-san arrives 20 minutes late to the meeting with no explanation. The Yokogawa junior staff appear unfazed. How does your team respond?',
                    textEs: '<strong>Complicacion:</strong> Nakamura-san llega 20 minutos tarde sin explicacion. El personal junior de Yokogawa parece tranquilo.',
                    options: [
                        { value: 'A', textEn: 'Proceed with the agenda as if nothing happened; begin when Nakamura-san is ready', textEs: 'Proceder con la agenda como si nada; comenzar cuando Nakamura-san este listo', trust: 8, dims: { cultural: 3, face: 2 } },
                        { value: 'B', textEn: 'Politely acknowledge the delay: "We noticed you were delayed — is everything alright?"', textEs: 'Reconocer el retraso educadamente', trust: -5, dims: { face: -2, cultural: -1 } },
                        { value: 'C', textEn: 'Express frustration about lost time and suggest compressing the agenda', textEs: 'Expresar frustracion y sugerir comprimir la agenda', trust: -12, dims: { face: -4, cultural: -3, comm: -2 } }
                    ]
                },
                {
                    id: 'informal_email',
                    textEn: '<strong>Complication:</strong> Thomas Becker sent an informal technical email directly to Tanaka-san — without going through Nakamura-san. The email has been forwarded internally and is being discussed. How do you address this?',
                    textEs: '<strong>Complicacion:</strong> Thomas Becker envio un correo tecnico informal directamente a Tanaka-san, sin pasar por Nakamura-san. Se esta discutiendo internamente.',
                    options: [
                        { value: 'A', textEn: 'Klaus Maurer privately acknowledges to Nakamura-san that the communication bypassed proper protocol and assures it will not recur', textEs: 'Klaus Maurer reconoce privadamente ante Nakamura-san que se salto el protocolo', trust: 6, dims: { face: 3, cultural: 2 } },
                        { value: 'B', textEn: 'Ignore the situation and hope it resolves itself', textEs: 'Ignorar la situacion', trust: -6, dims: { face: -2, cultural: -1 } },
                        { value: 'C', textEn: 'Defend the email as efficient communication between technical counterparts', textEs: 'Defender el correo como comunicacion eficiente entre tecnicos', trust: -10, dims: { face: -3, cultural: -3, comm: -2 } }
                    ]
                },
                {
                    id: 'golf_outing',
