        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastRecord = history[history.length - 1];
            var finalTrust = lastRecord.results ? lastRecord.results.trustTotal : 50;
            var totalTrustChange = history.reduce(function(s, r) { return s + (r.results ? r.results.trustChange : 0); }, 0);

            var performance = 'Needs Improvement';
            if (finalTrust >= 80) performance = 'Excellent — Strategic Partner';
            else if (finalTrust >= 65) performance = 'Good — Cautious Engagement';
            else if (finalTrust >= 50) performance = 'Fair — Transactional';
            else if (finalTrust >= 35) performance = 'Poor — Relationship Stress';

            var insights = [];
            if (finalTrust >= 80) {
                insights.push('Outstanding cultural competence. Yokogawa views VantageAxis as a true strategic partner.');
            } else if (finalTrust >= 65) {
                insights.push('Solid performance with room to deepen relationship investment and face-management skill.');
            } else if (finalTrust >= 50) {
                insights.push('Mixed signals sent. Review face-saving moments and communication calibration decisions.');
            } else {
                insights.push('Significant cultural friction generated. Study Hall context theory and face management strategies.');
            }

            return {
                finalTrust: finalTrust,
                totalTrustChange: totalTrustChange,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.trustTotal < 35) return window.mySimulation.t('hint_critical');
            if (results.trustChange < -10) return window.mySimulation.t('hint_major_loss');
            if (results.trustChange < 0) return window.mySimulation.t('hint_minor_loss');
            if (results.trustChange > 15) return window.mySimulation.t('hint_excellent');
            if (results.trustChange > 5) return window.mySimulation.t('hint_good');
            return null;
        }

