        _updateBriefing(state) {
            var period = (state.currentPeriod || 1);
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = round.briefingEn;
            }

            var roundNameEl = document.getElementById('roundNameDisplay');
            if (roundNameEl) {
                roundNameEl.textContent = round.nameEn;
            }

            var area = document.getElementById('decisionsArea');
            if (area) {
                var html = '';
                for (var i = 0; i < round.decisions.length; i++) {
                    var dec = round.decisions[i];
                    html += '<div class="bridgecomm-sim-decision-group">';
                    html += '<h5>' + dec.labelEn + '</h5>';
                    for (var j = 0; j < dec.options.length; j++) {
                        var opt = dec.options[j];
                        html += '<label><input type="radio" name="' + dec.id + '" value="' + j + '"><span> ' + opt.value + '. ' + opt.textEn + '</span></label>';
                    }
                    html += '</div>';
                }
                area.innerHTML = html;
            }

            var eventPanel = document.getElementById('eventPanel');
            var ds = state.domainState || {};
            if (period === 3 && eventPanel && !ds.eventHandled) {
                var evtIdx = ds.randomEventIndex;
                if (evtIdx !== undefined && evtIdx < 5 && this.RANDOM_EVENTS[evtIdx]) {
                    var evt = this.RANDOM_EVENTS[evtIdx];
                    eventPanel.style.display = 'block';
                    var evtText = document.getElementById('eventText');
                    if (evtText) evtText.innerHTML = evt.textEn;
                    var evtDec = document.getElementById('eventDecision');
                    if (evtDec) {
                        var evtHtml = '<div class="bridgecomm-sim-decision-group"><h5>Your Response</h5>';
                        for (var k = 0; k < evt.options.length; k++) {
                            evtHtml += '<label><input type="radio" name="eventChoice" value="' + k + '"><span> ' + evt.options[k].value + '. ' + evt.options[k].textEn + '</span></label>';
                        }
                        evtHtml += '</div>';
                        evtDec.innerHTML = evtHtml;
                    }
                } else {
                    eventPanel.style.display = 'none';
                }
            } else if (eventPanel && period !== 3) {
                eventPanel.style.display = 'none';
            }

            var dealPanel = document.getElementById('dealOutcomePanel');
            if (dealPanel && period < 4) {
                dealPanel.style.display = 'none';
            }
        }
